/**
 * 생성 파일 — 손으로 고치지 않는다. `pnpm gen:blog-images`(`scripts/gen-blog-images.ts`)가 블로그 글이 쓰는 콘솔 스크린샷(등록부
 * `src/site/blog/shots.ts` · `src/docs/shots.ts`)을 실제 콘솔 화면(로컬 미리보기 + 가짜 API 시나리오 `docs`)에서 찍어 쓴다. import 는 없다(값 파일).
 * 경로는 `/img/<해시>/blog-<id>-<lang>-<theme>.webp`(1년 immutable). `width`·`height` 는 이미지 픽셀(1.5배로 찍었다 — 화면 폭은 2/3).
 */

export interface BlogShotImage {
  readonly path: string;
  readonly width: number;
  readonly height: number;
  readonly hash: string;
  readonly bytes: number;
  readonly base64: string;
}

/** 찍은 배율 — 화면에 싣는 CSS 크기 = 픽셀 / 배율(문서 스크린샷 `DOCS_SHOT_VIEW.scale` 과 같다 — 테스트). */
export const BLOG_SHOT_SCALE = 1.5;

/** 언어별 두 테마 — 그 언어의 글이 쓰는 언어만 찍는다(영어 글만 쓰면 `en` 만). */
export type BlogShotSet = Readonly<Partial<Record<'ko' | 'en', Readonly<Record<'light' | 'dark', BlogShotImage>>>>>;

